/*
 * Compatibility stand-in, not GSAP. Pages generated by earlier versions of
 * nr_landingpage load this path and call gsap.from(), gsap.to() and
 * gsap.registerPlugin() from a script stored in the page. GSAP is no longer
 * shipped (see Documentation/Usage). This object accepts those calls without
 * animating, so the stored script does not fail: elements keep their final
 * appearance, and text that the typewriter script removed before calling
 * gsap.to(element, {text: ...}) is put back.
 */
(function () {
  'use strict';

  function elements(target) {
    if (typeof target === 'string') {
      return Array.prototype.slice.call(document.querySelectorAll(target));
    }
    if (target && target.nodeType === 1) {
      return [target];
    }
    return [];
  }

  window.gsap = {
    registerPlugin: function () {},
    matchMedia: function () {
      return { add: function () {} };
    },
    from: function () {},
    to: function (target, vars) {
      if (vars && typeof vars.text === 'string') {
        elements(target).forEach(function (element) {
          element.textContent = vars.text;
        });
      }
    }
  };
})();
